  FARMER: 'FARMER', // 种植户
  COLLECTOR: 'COLLECTOR', // 收料员
  REVIEWER: 'REVIEWER', // 审核人员
  ADMIN: 'ADMIN', // 管理员
} as const;

export const RECORD_STATUS = {
  PENDING: 'PENDING', // 已过磅，待分拣
  SORTED: 'SORTED', // 已分拣，待审核
  APPROVED: 'APPROVED', // 审核通过，进入补贴清单
  REJECTED: 'REJECTED', // 审核驳回，不计补贴
} as const;

