import { Module } from '@nestjs/common';
import { ScaleController } from './scale.controller';
import { ScaleService } from './scale.service';

@Module({
  controllers: [ScaleController],
  providers: [ScaleService],
  exports: [ScaleService],
})
export class ScaleModule {}

import { Injectable } from '@nestjs/common';

export interface ScaleReadingResult {
  grossKg: number;
  tareKg: number;
  netKg: number;
  stable: boolean;
  deviceId: string;
  readAt: string;
}

/**
 * 本地模拟地磅：
 * - stable=true 表示读数稳定；
 * - 读数保留两位小数并带微小抖动，模拟真实设备；
 * - 真实项目应替换为串口/地磅仪表驱动（如耀华 XK3190）。
 */
@Injectable()
export class ScaleService {
  private readonly deviceId = 'SCALE-SIM-01';

  private round2(n: number) {
    return Math.round(n * 100) / 100;
  }

  /** 读取一次完整过磅（毛重 + 皮重）。入参为期望重量，用于演示 */
  read(expectedGross = 120, expectedTare = 5): ScaleReadingResult {
    const jitter = () => this.round2((Math.random() - 0.5) * 0.2);
    const grossKg = Math.max(0, this.round2(expectedGross + jitter()));
    const tareKg = Math.max(0, this.round2(expectedTare + jitter() * 0.5));
    return {
      grossKg,
      tareKg,
      netKg: this.round2(grossKg - tareKg),
      stable: true,
      deviceId: this.deviceId,
      readAt: new Date().toISOString(),
    };
  }
}

import { Body, Controller, Post, UseGuards } from '@nestjs/common';
import { IsNumber, IsOptional, Min } from 'class-validator';
import { JwtAuthGuard } from '../auth/jwt-auth.guard';
import { Roles } from '../auth/roles.decorator';
import { ROLES } from '../domain';
import { ScaleService } from './scale.service';
import { PrismaService } from '../prisma/prisma.service';

class ReadScaleDto {
  @IsOptional()
  @IsNumber()
  @Min(0)
  expectedGross?: number;

  @IsOptional()
  @IsNumber()
  @Min(0)
  expectedTare?: number;

  @IsOptional()
  ticketNo?: string;
}

@UseGuards(JwtAuthGuard)
@Controller('scale')
export class ScaleController {
  constructor(
    private scale: ScaleService,
    private prisma: PrismaService,
  ) {}

  /** 收料员触发地磅读数（本地模拟），读数留痕 */
  @Roles(ROLES.COLLECTOR, ROLES.ADMIN)
  @Post('read')
  async read(@Body() dto: ReadScaleDto) {
    const result = this.scale.read(dto.expectedGross ?? 120, dto.expectedTare ?? 5);
    await this.prisma.scaleReading.create({
      data: {
        ticketNo: dto.ticketNo || `SIM-${Date.now()}`,
        grossKg: result.grossKg,
        tareKg: result.tareKg,
        stable: result.stable,
        deviceId: result.deviceId,
      },
    });
    return result;
  }
}

