  }

  /** 兑付清单：种植户只看自己的回执 */
  @Get()
  list(@CurrentUser() user: any, @Query('farmerId') farmerId?: string) {
    return this.payments.list(
      user.role === ROLES.FARMER ? { farmerId: user.id } : { farmerId: farmerId ? Number(farmerId) : undefined },
    );
  }
}

