:root {
  --green-700: #2f6b3a;
  --green-600: #3f7d4b;
  --green-100: #e4f1e6;
  --bg: #f4f6f2;
  --card: #ffffff;
  --border: #dde4da;
  --text: #23301f;
  --muted: #6a7568;
  --danger: #b43d3d;
  --danger-bg: #fbe9e9;
  --warn: #9a6b16;
  --warn-bg: #fdf3dd;
  --info-bg: #e7f0fb;
  --info: #2b5fa3;
  --radius: 10px;
  font-family: -apple-system, "PingFang SC", "Microsoft YaHei", "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--text); }

a { color: var(--green-700); }

.login-wrap {
  min-height: 100vh;
  display: flex; align-items: center; justify-content: center;
  background: linear-gradient(135deg, #2f6b3a 0%, #6aa177 100%);
  padding: 20px;
}
.login-card {
  background: var(--card); border-radius: 16px; padding: 36px 32px;
  width: 100%; max-width: 400px; box-shadow: 0 18px 50px rgba(0,0,0,.2);
}
.login-card h1 { margin: 0 0 4px; font-size: 22px; color: var(--green-700); }
.login-card p.sub { margin: 0 0 24px; color: var(--muted); font-size: 13px; }
.demo-accounts { margin-top: 20px; font-size: 12px; color: var(--muted); line-height: 1.9; }
.demo-accounts code { background: var(--green-100); padding: 1px 6px; border-radius: 4px; color: var(--green-700); }

.layout { min-height: 100vh; }
.topbar {
  background: var(--green-700); color: #fff; padding: 0 24px;
  display: flex; align-items: center; gap: 20px; height: 56px;
}
.topbar .brand { font-weight: 700; font-size: 16px; }
.topbar .spacer { flex: 1; }
.topbar .who { font-size: 13px; opacity: .9; }
.topbar button {
  background: rgba(255,255,255,.15); color: #fff; border: 1px solid rgba(255,255,255,.3);
  border-radius: 6px; padding: 5px 14px; cursor: pointer; font-size: 13px;
}
.topbar button:hover { background: rgba(255,255,255,.28); }
.tabs { display: flex; gap: 4px; }
.tabs button {
  background: transparent; color: rgba(255,255,255,.85); border: none; padding: 6px 12px;
  border-radius: 6px; cursor: pointer; font-size: 13px;
}
.tabs button.active { background: rgba(255,255,255,.22); color: #fff; font-weight: 600; }

.container { max-width: 1200px; margin: 24px auto; padding: 0 20px; }
.grid { display: grid; gap: 16px; }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
@media (max-width: 900px) { .grid-4, .grid-3, .grid-2 { grid-template-columns: 1fr; } }

.card {
  background: var(--card); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 18px 20px;
}
.card h2 { margin: 0 0 14px; font-size: 16px; }
.card h3 { margin: 18px 0 8px; font-size: 14px; color: var(--green-700); }

.stat .label { font-size: 13px; color: var(--muted); }
.stat .value { font-size: 26px; font-weight: 700; margin-top: 4px; }
.stat .unit { font-size: 13px; color: var(--muted); font-weight: 400; }

label.field { display: block; margin-bottom: 12px; font-size: 13px; color: var(--muted); }
label.field span { display: block; margin-bottom: 4px; }
input, select, textarea {
  width: 100%; padding: 9px 11px; border: 1px solid var(--border);
  border-radius: 7px; font-size: 14px; background: #fff; color: var(--text);
  font-family: inherit;
}
input:focus, select:focus, textarea:focus { outline: 2px solid var(--green-100); border-color: var(--green-600); }
textarea { resize: vertical; min-height: 60px; }

.btn {
  display: inline-flex; align-items: center; gap: 6px;
