            </div>
            <div>
              <b>分拣：</b>
              {detail.sortedNetWeightKg ?? '—'} kg / {detail.grade ?? '—'}
            </div>
            <div>
              <b>状态：</b>
              <Badge status={detail.status} />
            </div>
            <div>
              <b>核定补贴：</b>
              {detail.approvedSubsidyKg} kg / ¥{detail.subsidyYuan.toFixed(2)}
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

