  grade: string | null;
  status: string;
  rejectReason: string | null;
  suspectedDuplicate: boolean;
  approvedSubsidyKg: number;
  subsidyYuan: number;
  isPaid: boolean;
  createdAt: string;
  plot: { code: string; name: string };
  farmer: { name: string };
}
interface ScaleReading {
  grossKg: number;
  tareKg: number;
  netKg: number;
  stable: boolean;
  deviceId: string;
