  duplicateOfId: number | null;
  approvedSubsidyKg: number;
  subsidyYuan: number;
  cappedByPlot: boolean;
  cappedByPeriod: boolean;
  isPaid: boolean;
  createdAt: string;
  plot: { id: number; code: string; name: string; areaMu: number };
  farmer: { name: string };
